    self,
    ds: Any,
    schema: DatasetSchema,
    logical_to_actual: dict[str, str],
    error_handler: ErrorHandler,
) -> Any:
    """Fill default values for missing optional vars."""
    for logical, spec in schema.data_vars.items():
        if not isinstance(spec, DataVar):
