    ACTIVE = "active"
    INACTIVE = "inactive"

class Solution:
    def record_pane_state(self, window_id: str, pane_id: str, new_state: PaneStateName, *, provider: str='', last_active_ts: float | None=None) -> PaneStateName | None:
        """Upsert ``WindowState.panes`` entry; return the prior state or None."""
        if not isinstance(window_id, str) or not window_id.strip():
            raise TypeError("window_id must be a non-empty string")
        if not isinstance(pane_id, str) or not pane_id.strip():
            raise TypeError("pane_id must be non-empty string")

        # Assume WindowState is defined somewhere else
        from . import WindowState
        if window_id not in WindowState.panes:
            WindowState.panes[window_id] = {}
        if pane_id not in WindowState.panes[window_id]:
            WindowState.panes[window_id][pane_id] = {
                'state': None,
                'provider': '',
                'last_active_ts': None
            }

        old_state = WindowState.panes[window_id].get(pane_id, {}).get('state')
        WindowState.panes[window_id][pane_id]['state'] = new_state.value
        WindowState.panes[window_id][pane_id]['provider'] = provider
        WindowState.pans[window_id][pane_id]['last_active_ts'] = last_active_ts

        return old_state
